// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;

    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address actor, uint256 dummy) public {
        vm.assume(actor != address(0));
        vm.assume(uint160(actor) > 100);
        dummy; // widen the fuzz space
        // deploy the adversarial counterparty: a Bank-compatible contract
        // whose address c expects as msg.sender for supportsToken()
        Bank bank = new Bank();
        address caller = address(bank);
        // drive c through airDrop from the helper's address
        vm.prank(caller);
        bool ok;
        try c.airDrop() { ok = true; } catch { ok = false; }
        assertTrue(
            !ok || (c.tokenBalance(caller) == 20 && c.tokenBalance(actor) == 0),
            "successful airDrop must credit exactly 20 tokens"
        );
    }
}

contract Bank {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
